import java.util.Scanner;
interface Payment {void pay(double amount);void refund(double amount);}
class UPIPayment implements Payment {String upiId;int upiPin;double balance;UPIPayment(String id,int pin,double balance){upiId=id;upiPin=pin;this.balance=balance;}public void pay(double amount){Scanner sc=new Scanner(System.in);System.out.print("Enter UPI PIN: ");int pin=sc.nextInt();if(pin!=upiPin)System.out.println("UPI Payment Failed: Incorrect PIN.");else if(balance<amount)System.out.println("UPI Payment Failed: Insufficient Balance.");else{balance-=amount;System.out.println("UPI Payment Successful. Remaining Balance: "+balance);}}public void refund(double amount){balance+=amount;System.out.println("UPI Refund Successful. Updated Balance: "+balance);}}
class CardPayment implements Payment {double limit;CardPayment(String number,String holder,int cvv,double limit){this.limit=limit;}public void pay(double amount){if(limit>=amount){limit-=amount;System.out.println("Card Payment Successful. Remaining Limit: "+limit);}else System.out.println("Card Payment Failed: Limit Exceeded.");}public void refund(double amount){limit+=amount;System.out.println("Card Refund Successful. Updated Limit: "+limit);}}
class WalletPayment implements Payment {double balance;WalletPayment(String id,double balance){this.balance=balance;}public void pay(double amount){if(balance>=amount){balance-=amount;System.out.println("Wallet Payment Successful. Remaining Balance: "+balance);}else System.out.println("Wallet Payment Failed: Insufficient Balance.");}public void refund(double amount){balance+=amount;System.out.println("Wallet Refund Successful. Updated Balance: "+balance);}}
public class Program9 {public static void main(String[] args){Payment p=new UPIPayment("user@upi",1234,5000);p.pay(1000);p.refund(200);System.out.println("----------------------");p=new CardPayment("1234567812345678","Prathima",321,8000);p.pay(3000);p.refund(500);System.out.println("----------------------");p=new WalletPayment("wallet001",1500);p.pay(2000);p.refund(700);}}
